      return;
    }

    if (lower === 'watch') {
      console.log('Watched: ' + (state.watchedStrategies.length ? state.watchedStrategies.join(', ') : '<none>'));
      rl.prompt();
      return;
    }

    if (lower.startsWith('watch ')) {
