      return;
    }

    if (lower.startsWith('unwatch ')) {
      unwatchStrategy(input.slice('unwatch '.length));
      rl.prompt();
      return;
    }

    if (lower === 'sim') {
      console.log('Simulation: ' + (state.simulation ? 'on' : 'off'));
      rl.prompt();
      return;
    }

    if (lower === 'sim on') {
